## 🔐 Recommended Hardened Implementation

Below is a **drop‑in replacement** for `app.js` that addresses all the above points while staying minimal and readable.

```js
// app.js – Hardened version
/* eslint-disable no-console */

const express = require('express');
const helmet = require('helmet');                 // A05 – security headers
const cors = require('cors');                     // Control cross‑origin requests
const rateLimit = require('express-rate-limit'); // A01 – brute‑force / DoS mitigation
const morgan = require('morgan');                 // A09 – request logging
const { body, param, query, validationResult } = require('express-validator'); // Input validation (A03)
require('dotenv').config();                       // Keep secrets out of source

const app = express();

// ---------- Global Middleware ----------
app.use(helmet());                              // Sets X‑Content‑Type‑Options, CSP, HSTS, etc.
app.disable('x-powered-by');                    // Hide framework version (A05)

app.use(cors({
  origin: process.env.CORS_ORIGIN || 'https://my‑frontend.example.com',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  credentials: true,
}));                                            // Restrict who can call the API

// Body parsing with size limits (protects against large payload attacks)
app.use(express.json({ limit: '100kb' }));
app.use(express.urlencoded({ extended: false, limit: '100kb' }));

// Request logging – use 'combined' format for production
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// Rate limiting – 100 req/min per IP (adjust as needed)
const apiLimiter = rateLimit({
  windowMs: 60 * 1000,
  max: 100,
  standardHeaders: true,    // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false,
});
app.use('/users', apiLimiter);   // Apply only to potentially sensitive routes

// ---------- Helper – Central error formatter ----------
function handleValidationErrors(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Do not leak the exact validation rule set; give generic message
    return res.status(400).json({ error: 'Invalid request parameters' });
  }
  next();
}

// ---------- Routes ----------
app.get('/health', (req, res) => {
  // Do not expose unnecessary internal details
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Protected Users endpoint (A01 – Broken Access Control)
// In a real app you would replace the mock data with a DB call that uses
// parameterised queries (preventing injection – A03).
app.get(
  '/users',
  // Example: require a valid JWT (this placeholder can be swapped with any auth strategy)
  (req, res, next) => {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.status(401).json({ error: 'Missing or malformed token' });
    }
    // TODO: verify JWT / session here
    next();
  },
  (req, res) => {
    // Minimal data exposure – avoid sending raw email unless the client is authorized
    const publicUsers = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];
    res.json(publicUsers);
  }
);

// Example of a route that accepts user‑supplied data – shows how to validate/escape
app.post(
  '/echo',
  [
    body('message')
      .isString()
      .isLength({ max: 200 })
      .trim()
      .escape(), // Defensive escaping (A03)
  ],
  handleValidationErrors,
  (req, res) => {
    // Safe echo back – no injection risk because we escaped above
    res.json({ echoed: req.body.message });
  }
);

// ---------- Global error handler ----------
app.use((err, req, res, next) => {
  // Log the full error internally (do NOT send stack trace to client)
  console.error(err);
  if (res.headersSent) return next(err);
  res.status(500).json({ error: 'Internal server error' });
});

// ---------- Server bootstrap ----------
const PORT = process.env.PORT || 3000;

// For production you should run behind a TLS‑terminating reverse proxy (nginx, Traefik, etc.).
// If you must serve TLS directly, use the built‑in https module with a proper cert.
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

