## 2. Recommended Refactor (with code)

Below is a **drop‑in replacement** for `app.js`. It adds:

1. **Helmet** – sets a comprehensive set of security headers.
2. **dotenv** – loads configuration from environment variables (no hard‑coded secrets/ports).
3. **express-rate-limit** – basic DoS protection.
4. **cors** – explicit whitelist (or safe defaults).
5. **express-validator** – example of request‑validation middleware.
6. **Centralised error handler** – hides stack traces from clients.
7. **Basic JWT authentication middleware** (optional, but demonstrates how to protect `/users`).
8. **Structured logging** (via `morgan` or `pino`, here we use `morgan` for simplicity).

```js
// app.js – hardened starter for an Express API
require('dotenv').config(); // <-- loads .env (port, JWT secret, etc.)

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, param, query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const morgan = require('morgan');

const app = express();

// -----------------------
// 1. Global Middleware
// -----------------------

// Security headers
app.use(helmet());

// JSON body parsing (with size limit)
app.use(express.json({ limit: '100kb' }));

// Structured request logging (omit sensitive data)
app.use(morgan('combined'));

// CORS – change the origin array to match your front‑end domains
const corsOptions = {
  origin: process.env.CORS_ORIGIN?.split(',') || ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  credentials: true,
};
app.use(cors(corsOptions));

// Rate limiting – 100 requests per 15 min per IP (tweak as needed)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// -----------------------
// 2. Helper: Auth Middleware
// -----------------------
const authenticateJwt = (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or malformed Authorization header' });
  }

  const token = authHeader.split(' ')[1];
  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET);
    req.user = payload; // attach user info to request for later use
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
};

// -----------------------
// 3. Routes
// -----------------------

// Health check – no auth, minimal data
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Example: protected route that returns user list
app.get(
  '/users',
  authenticateJwt, // <-- protect the endpoint
  (req, res) => {
    // In a real app fetch from DB, apply RBAC checks, strip sensitive fields, etc.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    res.json(users);
  }
);

// Example of a route that accepts input – demonstrates validation & sanitisation
app.post(
  '/users',
  authenticateJwt,
  [
    body('name')
      .trim()
      .isLength({ min: 1, max: 50 })
      .withMessage('Name must be between 1‑50 characters'),
    body('email')
      .trim()
      .isEmail()
      .normalizeEmail()
      .withMessage('Valid e‑mail required'),
  ],
  (req, res) => {
    // Validate request body
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // At this point, data is already sanitised (trimmed, email normalised)
    const { name, email } = req.body;
    // TODO: insert into DB with parameterised queries / ORM to avoid SQLi
    res.status(201).json({ id: 3, name, email });
  }
);

// -----------------------
// 4. Central error handler
// -----------------------
app.use((err, req, res, next) => {
  console.error(err); // keep server logs for debugging / forensic analysis
  // Do NOT expose stack traces or internal messages to clients in production
  const status = err.status || 500;
  const response = { error: err.message || 'Internal Server Error' };
  if (process.env.NODE_ENV !== 'production' && err.stack) {
    response.stack = err.stack; // helpful during development only
  }
  res.status(status).json(response);
});

// -----------------------
// 5. Server start (configurable)
// -----------------------
const PORT = parseInt(process.env.PORT, 10) || 3000;
app.listen(PORT, () => {
  console.log(`🚀 Server running on port ${PORT}`);
});

module.exports = app;
```

### 2.1 What changed & why it matters

| Change | OWASP Top 10 mapping | Explanation |
|--------|----------------------|-------------|
| **Helmet** | A6 – Security Misconfiguration | Sets headers: CSP, X‑Frame‑Options, X‑Content‑Type‑Options, Referrer‑Policy, etc. |
| **express-rate-limit** | A5 / A10 | Throttles abusive clients before they can cause a DoS or scrape data. |
| **CORS whitelist** | A5 – Broken Access Control | Only trusted origins can make AJAX calls; avoids CSRF‑like attacks on APIs that rely on browsers. |
| **JWT auth middleware** | A2 – Broken Authentication, A5 – Broken Access Control | Requires a valid token for sensitive endpoints (`/users`). |
| **express-validator** | A1 – Injection, A3 – Sensitive Data Exposure | Validates & sanitises incoming data, prevents injection attacks (SQL, NoSQL, command, etc.). |
| **Centralised error handler** | A3 – Sensitive Data Exposure | Hides stack traces & internal messages in production. |
| **dotenv + env‑based config** | A5 – Broken Access Control / A6 | No secret values hard‑coded; port and JWT secret come from environment. |
| **Structured logging (morgan)** | A10 – Insufficient Logging & Monitoring | Gives an audit trail of requests & errors. |
| **JSON body size limit** | A5 – Broken Access Control | Prevents huge payload attacks. |
| **Rate‑limit JSON parsing & validation** | A5 – Broken Access Control | Together they mitigate request‑smuggling attacks. |

