```js
// app.js
// Secure example of a tiny Express service

/* --------------------------------------------------------------
   1️⃣  Dependencies – add security‑focused middleware
   -------------------------------------------------------------- */
const express = require('express');
const helmet = require('helmet');                 // security headers
const rateLimit = require('express-rate-limit'); // DoS protection
const cors = require('cors');                     // CORS policy
const morgan = require('morgan');                 // logging
const jwt = require('jsonwebtoken');              // simple auth demo
// const { body, query, validationResult } = require('express-validator'); // future validation

/* --------------------------------------------------------------
   2️⃣  App & basic hardening
   -------------------------------------------------------------- */
const app = express();

// Remove the default X-Powered-By header
app.disable('x-powered-by');

// Set a strong set of security headers
app.use(
  helmet({
    // You can customise CSP, Referrer‑Policy, etc. if needed
    contentSecurityPolicy: false, // turn on if you serve HTML
  })
);

// Enable CORS only for trusted origins (adjust as needed)
app.use(
  cors({
    origin: ['https://mytrusteddomain.com'], // <-- change to your front‑end domain(s)
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
  })
);

// Simple request logger (combined format goes to stdout)
app.use(morgan('combined'));

// Rate‑limit all routes – 100 requests per 15 min per IP
app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100,
    message: { error: 'Too many requests, please try again later.' },
    standardHeaders: true,
    legacyHeaders: false,
  })
);

// Body parsers (useful for future POST/PUT routes)
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

/* --------------------------------------------------------------
   3️⃣  Authentication helper (demo only)
   -------------------------------------------------------------- */
// In a real app you would store the secret securely (e.g., env var, Vault)
const JWT_SECRET = process.env.JWT_SECRET || 'change‑me‑to‑real‑secret';

/**
 * Middleware that checks for a valid JWT in the Authorization header.
 * If invalid or missing, responds with 401.
 */
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer <token>

  if (!token) {
    return res.status(401).json({ error: 'Missing token' });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user; // attach payload to request
    next();
  });
}

/* --------------------------------------------------------------
   4️⃣  Routes
   -------------------------------------------------------------- */

// Health‑check – public
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * Example protected route.
 * Only callers with a valid JWT can reach it.
 * In a production system you would also enforce role/permission checks.
 */
app.get('/users', authenticateToken, (req, res) => {
  // In a real service you would query a DB, applying proper RBAC.
  // Here we deliberately hide the e‑mail unless the user is an admin.
  const isAdmin = req.user && req.user.role === 'admin';

  const users = [
    { id: 1, name: 'Alice', email: isAdmin ? 'alice@example.com' : undefined },
    { id: 2, name: 'Bob', email: isAdmin ? 'bob@example.com' : undefined },
  ];

  res.json(users);
});

/* --------------------------------------------------------------
   5️⃣  Global error handler
   -------------------------------------------------------------- */
app.use((err, req, res, next) => {
  console.error(err); // You may replace this with a structured logger
  res.status(500).json({ error: 'Internal Server Error' });
});

/* --------------------------------------------------------------
   6️⃣  Server start
   -------------------------------------------------------------- */
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

