Below is a **minimal but production‑ready** version of `app.js` that addresses all of the above points. Feel free to copy‑paste the entire file or cherry‑pick the pieces you need.

```javascript
/**
 * app.js – Hardened Express API
 * -------------------------------------------------
 * Security hardening includes:
 *   • Helmet for security headers
 *   • CORS with whitelist
 *   • Rate limiting (OWASP A5/A7)
 *   • Input validation (future‑proof)
 *   • Simple JWT auth (example; replace with your auth strategy)
 *   • Centralised error handling & logging
 *   • HTTPS‑only enforcement (when behind a proxy)
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { body, param, query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');

// -------------------------------------------------------------------
// Configuration (pull from env for production)
const PORT = process.env.PORT || 3000;
const JWT_SECRET = process.env.JWT_SECRET || 'change‑me‑in‑prod';
const CORS_ORIGINS = (process.env.CORS_ORIGINS || 'http://localhost:3000')
  .split(',')
  .map(o => o.trim());

// -------------------------------------------------------------------
// App creation
const app = express();

// ---------------------------------------------------------------
// 1️⃣ Basic security middlewares
app.use(helmet());                                // Sets many secure headers (CSP, HSTS, etc.)
app.set('trust proxy', 1);                       // Required when behind a reverse‑proxy (NGINX, Heroku)
app.use(express.json({ limit: '10kb' }));        // Body parser with size limit to mitigate DoS

// ---------------------------------------------------------------
// 2️⃣ CORS – only allow known origins
app.use(
  cors({
    origin: (origin, callback) => {
      // Allow non‑browser (e.g., health checks) when origin === undefined
      if (!origin || CORS_ORIGINS.includes(origin)) {
        callback(null, true);
      } else {
        callback(new Error('Not allowed by CORS'));
      }
    },
    methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
    credentials: true,
  })
);

// ---------------------------------------------------------------
// 3️⃣ Rate limiting – protect against brute‑force, DoS, credential stuffing
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                // limit each IP to 100 requests per window
  message: { error: 'Too many requests, please try again later.' },
});
app.use('/api/', apiLimiter); // apply to any future /api routes

// ---------------------------------------------------------------
// 4️⃣ Request logging (Morgan) – useful for auditing
app.use(morgan('combined'));

// ---------------------------------------------------------------
// 5️⃣ Helper: authentication middleware (JWT example)
function authenticateJwt(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader) return res.status(401).json({ error: 'Missing Authorization header' });

  const token = authHeader.split(' ')[1];
  try {
    const payload = jwt.verify(token, JWT_SECRET);
    req.user = payload; // attach user info to request
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
}

// ---------------------------------------------------------------
// 6️⃣ Routes
// 6a) Health check – no auth, no rate‑limit (should stay lightweight)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// 6b) Users endpoint – now protected + input validation demonstration
app.get(
  '/users',
  authenticateJwt, // <-- protect route
  // Example of query‑string validation (even if not used now)
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('limit must be an integer between 1 and 100')
    .toInt(),
  (req, res) => {
    // Validation errors handling
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // In a real app, fetch from DB and apply the limit
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    const limit = req.query.limit || users.length;
    res.json(users.slice(0, limit));
  }
);

// ---------------------------------------------------------------
// 7️⃣ Central error handler (hide stack traces in production)
app.use((err, req, res, next) => {
  console.error(err); // you may forward to a logger service
  const status = err.status || 500;
  const message = app.get('env') === 'production' ? 'Internal Server Error' : err.message;
  res.status(status).json({ error: message });
});

// ---------------------------------------------------------------
// 8️⃣ Start server (HTTPS enforcement is handled by reverse‑proxy)
//     – W/ Docker/K8s you typically terminate TLS at the ingress.
// ---------------------------------------------------------------
app.listen(PORT, () => {
  console.info(`Server listening on port ${PORT}`);
});

module.exports = app;
```

### Explanation of Key Additions

| Section | Why it matters | How it mitigates OWASP issues |
|---------|----------------|--------------------------------|
| **Helmet** | Adds `Content‑Security‑Policy`, `X‑Content‑Type‑Options`, `Strict‑Transport‑Security`, etc. | A05 (Security Misconfiguration) & A02 (Cryptographic Failures) |
| **CORS whitelist** | Prevents browsers from allowing cross‑origin AJAX calls from malicious sites. | A01 (Broken Access Control) |
| **express-rate-limit** | Throttles abusive IPs and slows credential‑stuffing attacks. | A07 (Authentication Failures) & A04 (Insecure Design) |
| **Morgan logger** | Gives you request‑level visibility for audit and incident response. | A10 (Logging & Monitoring) |
| **authenticateJwt** | Demonstrates a typical auth guard that blocks unauthenticated access. | A01, A07 |
| **express-validator** | Centralised schema for any future user‑supplied data (query, body, params). | A03 (Injection) |
| **Error handler** | Hides stack traces from callers while still logging them internally. | A05 (Misconfiguration) |
| **express.json({ limit: '10kb' })** | Limits request body size to protect against large‑payload DoS. | A04 (Insecure Design) |
| **trust proxy + HSTS** | Guarantees that the `Strict‑Transport‑Security` header is sent only when TLS terminates at the front‑end proxy. | A02 (Cryptographic Failures) |

