// app.js – hardened Express starter
require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const winston = require('winston');

const app = express();

// ---------- Logging ----------
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [new winston.transports.Console()]
});

// ---------- Security Middleware ----------
app.use(helmet()); // secure headers
app.use(
  cors({
    origin: process.env.ALLOWED_ORIGINS?.split(',') || [],
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    credentials: true
  })
);

// General rate limiter (all routes)
app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100,
    handler: (req, res) => res.status(429).json({ error: 'Too many requests' })
  })
);

// ---------- Auth helper ----------
const authMiddleware = (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader) return res.sendStatus(401);
  const token = authHeader.split(' ')[1];
  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET);
    req.user = payload;
    next();
  } catch (e) {
    logger.warn('Invalid JWT', { ip: req.ip });
    return res.sendStatus(403);
  }
};

// ---------- Routes ----------
app.get('/health', (req, res) => {
  // optional secret protection
  const token = req.headers['x-health-token'];
  if (process.env.HEALTH_TOKEN && token !== process.env.HEALTH_TOKEN) {
    return res.sendStatus(403);
  }
  res.json({ status: 'ok' });
});

const usersLimiter = rateLimit({
  windowMs: 60 * 60 * 1000, // 1 h
  max: 20,
  message: { error: 'Too many requests to /users' }
});

app.get('/users', authMiddleware, usersLimiter, (req, res) => {
  // Example role‑check – only admins can see the list
  if (!req.user.roles?.includes('admin')) return res.sendStatus(403);
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' }
  ]);
});

// ---------- Error handling ----------
app.use((err, req, res, next) => {
  logger.error('Unhandled error', { error: err, url: req.originalUrl });
  res.status(500).json({ error: 'Internal server error' });
});

// ---------- Server ----------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server listening on port ${PORT}`);
});

module.exports = app;
```

