const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { allowedOrigins } = require('./config');

const healthRouter = require('./routes/health');
const usersRouter  = require('./routes/users');
const { errorHandler } = require('./middleware/errorHandler');
const { authenticate } = require('./middleware/auth');

const app = express();

// ---- Security middle‑wares -------------------------------------------------
app.use(helmet());                     // Sets CSP, HSTS, X‑Content‑Type‑Options, etc.
app.disable('x-powered-by');          // Hide framework fingerprint

app.use(cors({
  origin: allowedOrigins.length ? allowedOrigins : false, // whitelist
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  credentials: true,
}));

// Rate limiting: 100 requests per 15‑minute window per IP
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: { error: 'Too many requests, please try later.' },
}));

// JSON body parsing (will be needed for POST/PUT later)
app.use(express.json());

// ---- Routes ----------------------------------------------------------------
app.use('/health', healthRouter);

// Protected routes – authentication required
app.use('/users', authenticate, usersRouter);

// ---- Global error handler --------------------------------------------------
app.use(errorHandler);

module.exports = app;
```

### 2.3 `src/middleware/auth.js` – JWT‑based auth stub

```js
// src/middleware/auth.js
const jwt = require('jsonwebtoken');
const { jwtSecret } = require('../config');

function authenticate(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or malformed token' });
  }

  const token = authHeader.split(' ')[1];
  try {
    const payload = jwt.verify(token, jwtSecret);
    // attach user information for downstream handlers
    req.user = payload;
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

module.exports = { authenticate };
```

> **Note:** For a production app you’d also verify roles/permissions (e.g., `req.user.role === 'admin'`).

### 2.4 `src/middleware/errorHandler.js` – Centralised error handling

```js
// src/middleware/errorHandler.js
function errorHandler(err, req, res, next) { // eslint-disable-line no-unused-vars
  // Log the full error stack on the server side (use a real logger in prod)
  console.error(err);

  // Do not leak stack traces to the client
  const status = err.status || 500;
  const message = status === 500 ? 'Internal server error' : err.message;
  res.status(status).json({ error: message });
}

module.exports = { errorHandler };
```

