// src/routes/users.js
const express = require('express');
const { query, validationResult } = require('express-validator');
const router = express.Router();

// Sample static users – in a real app this would query a DB.
const ALL_USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob',   email: 'bob@example.com' },
];

/**
 * GET /users
 * Optional query param: ?fields=name,email   (comma‑separated whitelist)
 */
router.get(
  '/',
  // ---- Validation ---------------------------------------------------------
  query('fields')
    .optional()
    .customSanitizer(value => value.split(',').map(f => f.trim()))
    .custom(fields => {
      const allowed = ['id', 'name', 'email'];
      const invalid = fields.filter(f => !allowed.includes(f));
      if (invalid.length) {
        throw new Error(`Invalid fields: ${invalid.join(', ')}`);
      }
      return true;
    }),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ error: errors.array()[0].msg });
    }

    const { fields } = req.query;
    const result = fields
      ? ALL_USERS.map(u => {
          const obj = {};
          fields.forEach(f => (obj[f] = u[f]));
          return obj;
        })
      : ALL_USERS;

    // Note: In a real system you would **not** expose raw email addresses
    // unless the caller is authorized and the data is transmitted over TLS.
    res.json(result);
  }
);

module.exports = router;
```

