// config.js
const fs = require('fs');
const path = require('path');

// 1️⃣ Load .env for local dev (if present)
if (fs.existsSync(path.resolve(__dirname, '.env'))) {
  // eslint-disable-next-line global-require
  require('dotenv').config({ path: path.resolve(__dirname, '.env') });
}

// Helper to read a variable with a fallback/value check
function getEnv(name, required = true, fallback) {
  const value = process.env[name] ?? fallback;
  if (required && (value === undefined || value === '')) {
    throw new Error(`Missing required environment variable: ${name}`);
  }
  return value;
}

// 2️⃣ If we are in production, optionally pull from a secrets manager
async function loadSecretsFromAWS() {
  const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
  const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

  const secretName = process.env.AWS_SECRET_NAME; // e.g. "my-app/prod"
  if (!secretName) return; // no secret manager config → skip

  const command = new GetSecretValueCommand({ SecretId: secretName });
  const response = await client.send(command);
  const secretString = response.SecretString;
  const secrets = JSON.parse(secretString);

  // Merge fetched secrets into process.env (won’t overwrite if already set)
  Object.entries(secrets).forEach(([k, v]) => {
    if (!process.env[k]) process.env[k] = v;
  });
}

// Immediately invoke (non‑blocking for dev)
if (process.env.NODE_ENV === 'production') {
  // In production we want the secrets before the server starts.
  // Export a promise that the main file can await.
  module.exports = loadSecretsFromAWS().then(() => ({
    PORT: getEnv('PORT', false, 3000),
    CORS_ORIGIN: getEnv('CORS_ORIGIN', false, '*'),
    JWT_SECRET: getEnv('JWT_SECRET'),          // required
    DB_URI: getEnv('DB_URI'),                  // required for DB connections
    HEALTH_TOKEN: getEnv('HEALTH_TOKEN', false, undefined)
  }));
} else {
  // Development – sync config is fine
  module.exports = Promise.resolve({
    PORT: getEnv('PORT', false, 3000),
    CORS_ORIGIN: getEnv('CORS_ORIGIN', false, '*'),
    JWT_SECRET: getEnv('JWT_SECRET', false, 'dev‑secret'), // not for prod!
    DB_URI: getEnv('DB_URI', false, ''),
    HEALTH_TOKEN: getEnv('HEALTH_TOKEN')
  });
}
```

