```js
// ------------------------------------------------------------
// auth.js – tiny JWT auth helper (could be moved to its own file)
const jwt = require('jsonwebtoken');
const secret = process.env.JWT_SECRET || 'CHANGE_ME_IN_PROD';

// Middleware that verifies the token and attaches the user payload
function authenticate(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or malformed Authorization header' });
  }

  const token = authHeader.split(' ')[1];
  try {
    const payload = jwt.verify(token, secret);
    req.user = payload;          // payload may hold { sub, role, ... }
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
}

// Example role‑check – only admin can view full user list
function authorize(allowedRoles = []) {
  return (req, res, next) => {
    if (!req.user) return res.status(401).json({ error: 'Unauthenticated' });
    if (allowedRoles.length && !allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Forbidden' });
    }
    next();
  };
}
module.exports = { authenticate, authorize };
```

**Apply to `/users`:**

```js
const { authenticate, authorize } = require('./auth');

