```

```js
// app.js – add near the top, after `const app = express();`
const helmet = require('helmet');

// Hide implementation details
app.disable('x-powered-by');

// Apply a solid header baseline
app.use(
  helmet({
    // Example CSP – tighten as needed for your front‑end
    contentSecurityPolicy: {
      directives: {
        defaultSrc: ["'self'"],
        scriptSrc: ["'self'"],
        styleSrc: ["'self'"],
        imgSrc: ["'self' data:"],
        connectSrc: ["'self'"],
      },
    },
    // Enable HTTP Strict Transport Security (HSTS)
    hsts: {
      maxAge: 31536000, // 1 year in seconds
      includeSubDomains: true,
      preload: true,
    },
  })
);
```

### 2.2. Enforce HTTPS (Transport Security)

If the app runs behind a reverse proxy (e.g., Nginx, AWS ELB) you should tell Express to trust the proxy and reject insecure requests.

```js
// Trust the first proxy (typical when behind a load balancer)
app.set('trust proxy', 1);

// Redirect HTTP → HTTPS (optional, often done at the proxy level)
app.use((req, res, next) => {
  if (req.secure) {
    return next();
  }
  res.redirect(`https://${req.headers.host}${req.url}`);
});
```

