Below is a **re‑worked `app.js`** that addresses the findings above while staying as close as possible to the original functionality.

```javascript
// app.js
// Updated with security best‑practices (OWASP Top 10)

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const jwt = require('jsonwebtoken'); // Example auth library
const { body, param, query, validationResult } = require('express-validator');

const app = express();

// ---------------------------------------------------
// 1️⃣  General security hardening
// ---------------------------------------------------
app.use(helmet());                     // Sets secure HTTP headers
app.use(cors({                          // Restrict origins as needed
  origin: process.env.ALLOWED_ORIGINS?.split(',') || '*',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
}));
app.use(express.json());               // Parse JSON bodies safely
app.use(morgan('combined'));           // Request logging

// ---------------------------------------------------
// 2️⃣  Rate limiting (protects against brute‑force, DoS)
// ---------------------------------------------------
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,            // 15 minutes
  max: 100,                           // limit each IP to 100 requests per window
  message: { error: 'Too many requests, try again later.' },
});
app.use('/api/', apiLimiter);         // Apply to all API routes

// ---------------------------------------------------
// 3️⃣  Simple JWT authentication middleware (example)
// ---------------------------------------------------
const authMiddleware = (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader) return res.status(401).json({ error: 'Missing Authorization header' });

  const token = authHeader.split(' ')[1];
  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET);
    req.user = payload;               // payload typically contains { sub, role, ... }
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token' });
  }
};

// ---------------------------------------------------
// 4️⃣  Input validation helpers
// ---------------------------------------------------
const validate = (validations) => async (req, res, next) => {
  await Promise.all(validations.map((v) => v.run(req)));
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

// ---------------------------------------------------
// 5️⃣  Routes
// ---------------------------------------------------

// Health check – no auth needed
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * GET /api/users
 * Returns user list – **protected** and PII‑redacted.
 */
app.get(
  '/api/users',
  authMiddleware,                     // 👈 require a valid JWT
  (req, res) => {
    // In a real app this would come from a DB.
    const users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ];
    res.json(users);
  }
);

/**
 * Example of a route that **does accept** user input
 * (to demonstrate validation & sanitisation).
 */
app.post(
  '/api/users',
  authMiddleware,
  validate([
    body('name')
      .trim()
      .isLength({ min: 2, max: 50 })
      .withMessage('Name must be 2‑50 characters long')
      .escape(),
    body('email')
      .isEmail()
      .normalizeEmail()
      .withMessage('Valid email required')
      .customSanitizer((value) => value.toLowerCase()),
  ]),
  (req, res) => {
    // Here you would insert into DB using a parameterised query / ORM.
    const { name, email } = req.body;
    // Example response (do not echo back email unless authorized)
    res.status(201).json({ id: Date.now(), name });
  }
);

// ---------------------------------------------------
// 6️⃣  Centralised error handling (prevents stack traces leaking)
// ---------------------------------------------------
app.use((err, _req, res, _next) => {
  console.error(err);                 // Keep logs for ops/security teams
  res.status(500).json({ error: 'Internal Server Error' });
});

// ---------------------------------------------------
// 7️⃣  Server start
// ---------------------------------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;
```

### What Changed?

