const JWT_SECRET = process.env.JWT_SECRET || 'change‑me‑to‑strong‑random';

// ---- Middleware stack -------------------------------------------------
app.use(helmet());                     // A5 – adds many security headers
app.use(cors({                         // A5 – restrict origins (replace with your domains)
  origin: process.env.CORS_ORIGIN ? process.env.CORS_ORIGIN.split(',') : '*',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
}));
app.use(express.json({ limit: '100kb' })); // protect against large payloads
app.use(morgan('combined'));           // A10 – request logging

// ---- Rate limiting (global) -------------------------------------------
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

