  '/login',
  // Input validation – prevent injection, malformed data (A1)
  [
    body('username').isString().trim().isLength({ min: 3, max: 30 }),
    body('password').isString().trim().isLength({ min: 6, max: 128 }),
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const { username, password } = req.body;
    // **Never** store plain passwords – this is just a demo.
    // In production you would compare a hashed password from DB.
    if (username === 'admin' && password === 'supersecret') {
      const token = jwt.sign({ sub: username, role: 'admin' }, JWT_SECRET, {
        expiresIn: '1h',
      });
      return res.json({ token });
    }
    return res.status(401).json({ message: 'Invalid credentials' });
  }
);

/* -------------------- Centralized Error Handling (A10) -------------------- */
app.use((err, req, res, next) => {
  console.error(err); // still log stack trace internally
