## 3. Specific Recommendations & Code Samples

### 3.1. Add Basic Security Middleware

```js
// security.js  (optional – keep it separate for readability)
const helmet = require('helmet');               // Secure HTTP headers
const cors   = require('cors');                 // Define allowed origins
const rateLimit = require('express-rate-limit'); // DoS protection
const xssClean = require('xss-clean');           // Basic XSS sanitisation

module.exports = (app) => {
  // Trust proxy headers if behind a load‑balancer (e.g., Heroku)
  app.set('trust proxy', 1);

  // Helmet sets many headers (Content‑Security‑Policy, HSTS, etc.)
  app.use(helmet());

  // CORS – adjust the origin list to your client domains
  app.use(cors({
    origin: ['https://my-site.example.com'],
    methods: ['GET','POST','PUT','DELETE'],
    credentials: true,
  }));

  // Rate limiting – 100 req/min per IP (tune as needed)
  const limiter = rateLimit({
    windowMs: 60 * 1000,
    max: 100,
    standardHeaders: true,
    legacyHeaders: false,
  });
  app.use(limiter);

  // Simple XSS sanitiser for query/body strings
  app.use(xssClean());

  // JSON body parser (needed for POST/PUT)
  app.use(express.json({ limit: '10kb' })); // limit payload size
};
```

**Add to `app.js`** (near the top, after creating `app`):

