### 3.3. Authentication & Authorization (JWT Example)

1. **Install dependencies**

```bash
npm install jsonwebtoken bcryptjs express-validator
```

2. **Create a simple auth module**

```js
// auth.js
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');
const { body, validationResult } = require('express-validator');

const JWT_SECRET = process.env.JWT_SECRET || 'CHANGE_ME_TO_RANDOM_64CHAR';
const JWT_EXPIRES = '1h';

// Dummy user store – replace with a real DB in production
const users = [
  // Passwords should be pre‑hashed with bcrypt; here we store plain for demo only
  { id: 1, username: 'admin', passwordHash: bcrypt.hashSync('P@ssw0rd!', 10), role: 'admin' },
];

/* Middleware to protect routes */
function authenticate(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing token' });
  }
  const token = authHeader.split(' ')[1];
  try {
    const payload = jwt.verify(token, JWT_SECRET);
    req.user = payload; // attach user info to request
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

/* Role‑based guard */
function authorize(allowedRoles = []) {
  return (req, res, next) => {
    if (!allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Forbidden' });
    }
    next();
  };
}

/* Login endpoint – validates input */
const loginValidators = [
  body('username').trim().isLength({ min: 1 }).withMessage('username required'),
  body('password').isLength({ min: 6 }).withMessage('password required'),
];

function loginHandler(req, res) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const { username, password } = req.body;
  const user = users.find(u => u.username === username);
  if (!user || !bcrypt.compareSync(password, user.passwordHash)) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const token = jwt.sign(
    { sub: user.id, username: user.username, role: user.role },
    JWT_SECRET,
    { expiresIn: JWT_EXPIRES }
  );

  res.json({ token });
}

module.exports = { authenticate, authorize, loginValidators, loginHandler };
```

3. **Wire it up in `app.js`**

```js
const { authenticate, authorize, loginValidators, loginHandler } = require('./auth');

// Public route – login
app.post('/login', loginValidators, loginHandler);

// Protected route – example: only admins can see the users list
app.get('/users', authenticate, authorize(['admin']), (req, res) => {
  // In a real app pull from DB; keep static list for demo
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

Now `/users` is **not publicly accessible**; only a valid JWT with role `admin` can retrieve it.

### 3.4. Input Validation & Sanitisation (Express‑Validator)

Even if you currently have only GET endpoints, any future POST/PUT routes should validate everything that comes from the client.

```js
// Example: create a new user (POST /users)
const { body } = require('express-validator');

app.post(
  '/users',
  authenticate,
  authorize(['admin']),
  [
    body('name')
      .trim()
      .isLength({ min: 1, max: 100 })
      .withMessage('Name is required, max 100 chars'),
    body('email')
      .trim()
      .isEmail()
      .withMessage('Valid email required')
      .normalizeEmail(),
    body('password')
      .isStrongPassword()
      .withMessage('Password must be strong')
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Save user … (hash password before storing)
    res.status(201).json({ message: 'User created' });
  }
);
```

**Why:** Prevent injection attacks (SQL/NoSQL), enforce proper data types, cut down on XSS vectors.

