const JWT_EXPIRES_IN = '1h';

// ----- middleware ----------------------------------------------------
app.use(
  expressJwt({
    secret: JWT_SECRET,
    algorithms: ['HS256'],
  }).unless({ path: ['/health', '/login'] }) // public routes
);

// ----- login route (returns a token) ---------------------------------
app.post('/login', express.json(), (req, res) => {
  const { username, password } = req.body;

  // TODO: replace with real credential check (hash compare, DB lookup)
  if (username === 'admin' && password === 's3cr3t') {
    const token = jwt.sign({ sub: username, role: 'admin' }, JWT_SECRET, {
      expiresIn: JWT_EXPIRES_IN,
    });
    return res.json({ token });
  }

  res.status(401).json({ error: 'Invalid credentials' });
});
```

Now the `/users` endpoint will only be reachable when a valid **Bearer token** is supplied:

```js
app.get('/users', (req, res) => {
  // req.auth is populated by `express-jwt`
  if (req.auth.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

> **Alternative** – If you only need a quick demo, a simple API‑key header can be used:

