## Example: Refactor to Use a Secrets Manager (AWS Secrets Manager shown)

1. **Add the AWS SDK**  

   ```bash
   npm i @aws-sdk/client-secrets-manager
   ```

2. **Create a tiny wrapper (`secretProvider.js`)**  

   ```js
   // secretProvider.js
   const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

   const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

   async function loadSecret(secretId) {
     const cmd = new GetSecretValueCommand({ SecretId: secretId });
     const data = await client.send(cmd);
     return data.SecretString ? JSON.parse(data.SecretString) : {};
   }

   // Export a promise that resolves once all needed secrets are loaded
   async function init() {
     const appSecrets = await loadSecret('myApp/config'); // e.g. stores { jwtSecret, dbUrl, apiKey }
     process.env.JWT_SECRET = appSecrets.jwtSecret;
     process.env.DATABASE_URL = appSecrets.dbUrl;
     process.env.API_KEY = appSecrets.apiKey;
   }

   module.exports = { init };
   ```

3. **Use it at startup (early in `app.js`)**  

   ```js
   const { init: loadSecrets } = require('./secretProvider');

   (async () => {
     try {
       await loadSecrets();                     // pulls secrets into process.env
       const app = require('./app');            // now the rest of the app can read process.env safely
       const PORT = process.env.PORT || 3000;
       app.listen(PORT, () => console.log(`Server on ${PORT}`));
     } catch (e) {
       console.error('Failed to load secrets:', e);
       process.exit(1);
     }
   })();
   ```

4. **Remove `.env` from production** – keep it only for local development, and ensure it is listed in `.gitignore`.

